en:
//【景明】
<voice name='景明' class='景明' src='voice/ma03/0110970a00'>
//「<RUBY text='スタンド'>観客席</RUBY>など無くて当然、芝生の上に<RUBY text='ござ'>茣蓙</RUBY>を
